CREATE TABLE IF NOT EXISTS attendance_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',title TEXT NOT NULL,subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,starts_at TEXT,ends_at TEXT,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,subject_component,subject_type,subject_id,title));
CREATE TABLE IF NOT EXISTS attendance_records (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL,party_type TEXT NOT NULL CHECK(party_type IN ('user','staff','student','guardian','team','external')),party_id TEXT NOT NULL,attendance_status TEXT NOT NULL DEFAULT 'expected' CHECK(attendance_status IN ('expected','present','absent','late','excused')),notes TEXT,checked_at TEXT,checked_by TEXT,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(session_id,party_type,party_id),FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_attendance_sessions ON attendance_sessions(app_id,status,starts_at);CREATE INDEX IF NOT EXISTS idx_attendance_records ON attendance_records(session_id,attendance_status);
